3	// Command-line regression tests for health queries over disconnected and
4	// replayed telemetry. The domain rules have focused tests in package
5	// edgefleet; these tests pin what a user actually sees through the real
6	// `edgefleet heartbeat health` entry point:
7	//
8	//   - when a node stores a stale greater-seq record and a fresh smaller-seq
9	//     record that arrived in either order, the health line must be built
10	//     entirely from the greatest seq — offline, with that record's time,
11	//     version, height and cumulative missed — never spliced with the fresh
12	//     record and never flipped online by its newer collection time;
13	//   - a late backfill or a verbatim duplicate of the smaller seq submitted at
14	//     an even later receive time changes neither the result nor the saved
15	//     file;
16	//   - the online edge is exact at nanosecond precision (60s online, 60s+1ns
17	//     offline) while the terminal keeps printing collection time as whole
18	//     seconds, and timezone re-spellings of the same instants agree;
19	//   - a missed-since baseline changes only the alarm quantity: the first line
20	//     still shows the greatest-seq record and its cumulative count, and the
21	//     baseline never decides online status;
22	//   - a query time earlier than the greatest-seq record's collection time is
23	//     an error (non-zero exit, reason on stderr, nothing on stdout) for both
24	//     plain and baseline queries, even though a smaller-seq record had already
25	//     been collected by then; offline itself is a successful query that
26	//     exits zero;
27	//   - no query, failed query or duplicate submission rewrites the saved
28	//     heartbeats.
29	
30	import (
31		"os"
32		"strings"
33		"testing"
34	)
35	
36	const (
37		// The disordered scenario uses a fixed query instant (same as the other
38		// CLI tests) and two records:
39		//
40		//	seq 10 collected 11:58:00 (2 minutes old, offline), version 1.25.0,
41		//	        height 1000, cumulative missed 5;
42		//	seq  5 collected 11:59:50 (10 seconds old, fresh), version 1.26.0,
43		//	        height 900, cumulative missed 2.
44		reconnectNode         = "backfill"
45		reconnectLatestLine   = "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0 missed duties above tolerance]"
46		reconnectStaleReceive = "2026-10-01T11:58:30Z"
47	)
48	
49	const reconnectStaleRecord = `{"node":"backfill","seq":10,"collected_at":"2026-10-01T11:58:00Z","version":"1.25.0","height":1000,"missed":5}`
50	const reconnectFreshRecord = `{"node":"backfill","seq":5,"collected_at":"2026-10-01T11:59:50Z","version":"1.26.0","height":900,"missed":2}`
51	
52	// submitWithReceive runs one submit command with an explicit receive time.
53	func submitWithReceive(t *testing.T, dir, json, receiveAt string) {
54		t.Helper()
55		out, errOut, code := runCLI(t, dir, json,
56			"heartbeat", "submit", "--data-dir", dir, "--receive-time", receiveAt)
57		if code != 0 {
58			t.Fatalf("submit at %s exited %d: stderr=%q stdout=%q", receiveAt, code, errOut, out)
59		}
60	}
61	
62	// healthQueryAt runs a health command with an explicit query instant.
63	func healthQueryAt(t *testing.T, dir, at string, args ...string) (string, string, int) {
64		t.Helper()
65		full := append([]string{"heartbeat", "health", "--data-dir", dir, "--at", at}, args...)
66		return runCLI(t, dir, "", full...)
67	}
