207	// TestCLIHealthSubSecondBoundaryAndWholeSecondDisplay protects the exact
208	// 60-second edge with fractional instants. The terminal prints collection
209	// time without its fraction, so both queries display 12:00:00 while one is
210	// exactly 60s old (online) and the other 60s+1ns old (offline, exit zero).
211	// Re-spelling the same instants in other timezones must not change either
212	// verdict, and the fraction must remain persisted in the saved file.
213	func TestCLIHealthSubSecondBoundaryAndWholeSecondDisplay(t *testing.T) {
214		dir := t.TempDir()
215		submitWithReceive(t, dir,
216			`[{"node":"frac","seq":1,"collected_at":"2026-10-01T12:00:00.5Z","version":"1.0","height":100,"missed":0}]`,
217			"2026-10-01T12:02:00Z")
218	
219		// Exactly 60 seconds old: online. Both instants carry the .5 fraction.
220		out, errOut, code := healthQueryAt(t, dir, "2026-10-01T12:01:00.5Z",
221			"--node", "frac", "--expected-version", "1.0", "--tolerated-misses", "0")
222		if code != 0 {
223			t.Fatalf("online query must exit 0, got %d: %q", code, errOut)
224		}
225		if !strings.Contains(out, "status=online") {
226			t.Errorf("at exactly 60s want online: %q", out)
227		}
228		// Existing terminal format: whole seconds, no fractional digits.
229		if !strings.Contains(out, "collected_at=2026-10-01T12:00:00Z") {
230			t.Errorf("collection time must keep the whole-second RFC3339 display: %q", out)
231		}
232		if strings.Contains(out, "12:00:00.5") {
233			t.Errorf("terminal display must stay whole-second compatible: %q", out)
234		}
235	
236		// One nanosecond beyond the window: offline with the offline notice, still
237		// a successful command.
238		out, errOut, code = healthQueryAt(t, dir, "2026-10-01T12:01:00.500000001Z",
239			"--node", "frac", "--expected-version", "1.0", "--tolerated-misses", "0")
240		if code != 0 {
241			t.Fatalf("offline is a query result, not an input error: exit=%d stderr=%q", code, errOut)
242		}
243		if errOut != "" {
244			t.Errorf("offline notice belongs on stdout, stderr=%q", errOut)
245		}
246		if !strings.Contains(out, "status=offline") || !strings.Contains(out, "findings=[offline]") {
247			t.Errorf("at 60s+1ns want offline with findings=[offline]: %q", out)
248		}
249		// Both verdicts print the identical whole-second time; judging by the
250		// displayed whole seconds could not tell them apart.
251		if !strings.Contains(out, "collected_at=2026-10-01T12:00:00Z") {
252			t.Errorf("offline line must display the same whole-second time: %q", out)
253		}
254	
255		// Same instants, different timezone spellings: the verdicts agree.
256		out, _, code = healthQueryAt(t, dir, "2026-10-01T20:01:00.5+08:00",
257			"--node", "frac", "--expected-version", "1.0", "--tolerated-misses", "0")
258		if code != 0 || !strings.Contains(out, "status=online") {
259			t.Errorf("+08:00 spelling of the exact boundary: code=%d out=%q, want online", code, out)
260		}
261		out, errOut, code = healthQueryAt(t, dir, "2026-10-01T08:01:00.500000001-04:00",
262			"--node", "frac", "--expected-version", "1.0", "--tolerated-misses", "0")
263		if code != 0 || !strings.Contains(out, "status=offline") {
264			t.Errorf("-04:00 spelling of 60s+1ns: code=%d out=%q stderr=%q, want offline/exit 0", code, out, errOut)
265		}
266	
267		// The fraction stays exact in stored telemetry even though the terminal
268		// renders whole seconds, and history uses the same display format.
269		if raw := readNodeFile(t, dir, "frac"); !strings.Contains(raw, "2026-10-01T12:00:00.5Z") {
270			t.Errorf("fractional collection time must be preserved on disk: %s", raw)
271		}
272		lines := historyLines(t, dir, "frac")
273		if len(lines) != 1 || !strings.Contains(lines[0], "collected_at=2026-10-01T12:00:00Z") {
274			t.Errorf("history display = %q, want whole-second collected_at", lines)
275		}
276	}
277	
278	// TestCLIHealthBaselineKeepsGreatestSeqAndCumulative checks that a
279	// missed-since baseline changes only the missed-duty alarm basis: the latest
280	// record is still seq 10 with its stale time (offline), version skew and
281	// cumulative missed=5 on the first line; the baseline seq 5 contributes only
282	// the second line. It must never decide online status.
283	func TestCLIHealthBaselineKeepsGreatestSeqAndCumulative(t *testing.T) {
284		dir := t.TempDir()
285		seedReconnectStored(t, dir)
286	
287		// new missed = 5-2 = 3, tolerance 2: alarm; status is still offline.
288		out, errOut, code := healthQueryAt(t, dir, cliQueryAt,
289			"--node", reconnectNode, "--expected-version", "1.26.0",
290			"--tolerated-misses", "2", "--missed-since-seq", "5")
291		if code != 0 {
292			t.Fatalf("baseline query must exit 0, got %d: %q", code, errOut)
293		}
294		lines := outputLines(out)
295		if len(lines) != 2 {
296			t.Fatalf("want two lines, got %q", out)
297		}
298		wantFirst := "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0 missed duties above tolerance]"
299		if lines[0] != wantFirst {
300			t.Errorf("first line = %q\nwant          %q", lines[0], wantFirst)
301		}
302		if strings.Contains(lines[0], "missed=2") {
303			t.Errorf("first line must show cumulative missed=5, not the baseline count: %q", lines[0])
304		}
305		if lines[1] != "baseline_seq=5 baseline_missed=2 new_missed=3 tolerated_misses=2" {
306			t.Errorf("second line = %q", lines[1])
307		}
308	
309		// new=3 with tolerance 3 silences the miss alarm but leaves offline and
310		// the seq-10 version skew untouched: the baseline does not decide status.
311		out, _, code = healthQueryAt(t, dir, cliQueryAt,
312			"--node", reconnectNode, "--expected-version", "1.26.0",
313			"--tolerated-misses", "3", "--missed-since-seq", "5")
314		if code != 0 {
315			t.Fatalf("exit=%d out=%q", code, out)
316		}
317		lines = outputLines(out)
318		wantFirst = "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0]"
319		if lines[0] != wantFirst {
320			t.Errorf("first line with silent miss alarm = %q\nwant                                %q", lines[0], wantFirst)
321		}
322		if lines[1] != "baseline_seq=5 baseline_missed=2 new_missed=3 tolerated_misses=3" {
323			t.Errorf("second line = %q", lines[1])
324		}
325	
326		// Baseline equal to the latest record: new missed 0, still offline.
327		out, _, code = healthQueryAt(t, dir, cliQueryAt,
328			"--node", reconnectNode, "--expected-version", "1.26.0",
329			"--tolerated-misses", "0", "--missed-since-seq", "10")
330		if code != 0 {
331			t.Fatalf("exit=%d out=%q", code, out)
332		}
333		lines = outputLines(out)
334		if !strings.Contains(lines[0], "status=offline") || !strings.Contains(lines[0], "seq=10") {
335			t.Errorf("baseline==latest must stay offline on seq 10: %q", lines[0])
336		}
337		if lines[1] != "baseline_seq=10 baseline_missed=5 new_missed=0 tolerated_misses=0" {
338			t.Errorf("second line = %q", lines[1])
339		}
340	}
341	
342	// TestCLIHealthQueryBeforeLatestSeqFailsWithoutFallback stores a node whose
343	// smaller-seq record genuinely exists before the requested query instant
344	// while the greatest-seq record does not exist yet. Both the plain query and
345	// a query with a valid baseline must fail non-zero with a reason on stderr
346	// and no health line on stdout — never silently rewinding to the older record
347	// and reporting it healthy.
348	func TestCLIHealthQueryBeforeLatestSeqFailsWithoutFallback(t *testing.T) {
349		dir := t.TempDir()
350		// seq 4 collected 11:57:00; seq 8 collected 11:58:00. Query at 11:57:30:
351		// seq 4 has already been collected, but the query is 30s before seq 8.
352		submitBatch(t, dir, `[
353		  {"node":"older","seq":4,"collected_at":"2026-10-01T11:57:00Z","version":"1.0","height":400,"missed":1},
354		  {"node":"older","seq":8,"collected_at":"2026-10-01T11:58:00Z","version":"1.0","height":404,"missed":3}
355		]`)
356		const earlyAt = "2026-10-01T11:57:30Z"
357	
358		cases := []struct {
359			name string
360			args []string
361		}{
362			{"plain query", []string{"--node", "older", "--expected-version", "1.0", "--tolerated-misses", "0"}},
363			{"query with valid baseline", []string{"--node", "older", "--expected-version", "1.0",
364				"--tolerated-misses", "0", "--missed-since-seq", "4"}},
365		}
366		for _, tc := range cases {
367			t.Run(tc.name, func(t *testing.T) {
368				out, errOut, code := healthQueryAt(t, dir, earlyAt, tc.args...)
369				if code == 0 {
370					t.Errorf("query before the greatest-seq record's collection time must exit non-zero; stdout=%q", out)
371				}
372				if !strings.Contains(errOut, "error:") || !strings.Contains(errOut, "earlier than collection") {
373					t.Errorf("stderr must explain the time ordering, got %q", errOut)
374				}
375				if out != "" {
376					t.Errorf("no health result may be printed when the query is rejected, stdout=%q", out)
377				}
378			})
379		}
380	
381		// At the exact greatest-seq collection instant the query succeeds and
382		// reports seq 8 (age 0, online); the rejection is strictly about time.
383		out, errOut, code := healthQueryAt(t, dir, "2026-10-01T11:58:00Z",
384			"--node", "older", "--expected-version", "1.0", "--tolerated-misses", "9")
385		if code != 0 {
386			t.Fatalf("query at the exact latest collection instant must succeed: %d %q", code, errOut)
387		}
388		if !strings.Contains(out, "seq=8") || !strings.Contains(out, "status=online") {
389			t.Errorf("exact-boundary query = %q, want seq=8 online", out)
390		}
391	}
392	
393	// TestCLIHealthQueriesAndFailuresDoNotRewriteStore snapshots the saved node
394	// files, exercises successful and failing reads of every kind plus a
395	// duplicate replay, and requires byte-identical storage and no file for a
396	// queried unknown node.
397	func TestCLIHealthQueriesAndFailuresDoNotRewriteStore(t *testing.T) {
398		dir := t.TempDir()
399		seedReconnectStored(t, dir)
400		submitBatch(t, dir, `[
401		  {"node":"older","seq":4,"collected_at":"2026-10-01T11:57:00Z","version":"1.0","height":400,"missed":1},
402		  {"node":"older","seq":8,"collected_at":"2026-10-01T11:58:00Z","version":"1.0","height":404,"missed":3}
403		]`)
404	
405		before := map[string]string{}
406		for _, node := range []string{reconnectNode, "older"} {
407			before[node] = readNodeFile(t, dir, node)
408		}
409	
410		// Successful offline query, baseline variants, and a notelemetry answer.
411		healthQueryAt(t, dir, cliQueryAt, "--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
412		healthQueryAt(t, dir, cliQueryAt, "--node", reconnectNode, "--expected-version", "1.26.0",
413			"--tolerated-misses", "2", "--missed-since-seq", "5")
414		out, _, code := healthQueryAt(t, dir, cliQueryAt, "--node", "ghost", "--expected-version", "1.0", "--tolerated-misses", "0")
415		if code != 0 || !strings.Contains(out, "status=无遥测") {
416			t.Fatalf("unknown node query: code=%d out=%q, want notelemetry/exit 0", code, out)
417		}
418	
419		// Failing reads: early plain and baseline queries, unknown/missing/too-large
420		// baselines, baseline on a node without telemetry.
421		if _, _, c := healthQueryAt(t, dir, "2026-10-01T11:57:30Z",
422			"--node", "older", "--expected-version", "1.0", "--tolerated-misses", "0"); c == 0 {
423			t.Error("early plain query should exit non-zero")
424		}
425		if _, _, c := healthQueryAt(t, dir, "2026-10-01T11:57:30Z",
426			"--node", "older", "--expected-version", "1.0", "--tolerated-misses", "0",
427			"--missed-since-seq", "4"); c == 0 {
428			t.Error("early baseline query should exit non-zero")
429		}
430		if _, _, c := healthQueryAt(t, dir, cliQueryAt, "--node", reconnectNode, "--expected-version", "1.26.0",
431			"--tolerated-misses", "0", "--missed-since-seq", "7"); c == 0 {
432			t.Error("baseline seq 7 (never saved) should exit non-zero")
433		}
434		if _, _, c := healthQueryAt(t, dir, cliQueryAt, "--node", reconnectNode, "--expected-version", "1.26.0",
435			"--tolerated-misses", "0", "--missed-since-seq", "11"); c == 0 {
436			t.Error("baseline above the latest seq should exit non-zero")
437		}
438		if _, _, c := healthQueryAt(t, dir, cliQueryAt, "--node", "ghost", "--expected-version", "1.0",
439			"--tolerated-misses", "0", "--missed-since-seq", "1"); c == 0 {
440			t.Error("baseline on a node without telemetry should exit non-zero")
441		}
442	
443		// Querying an unknown node must not create its file.
444		if _, err := os.Stat(nodeFileHexPath(dir, "ghost")); !os.IsNotExist(err) {
445			t.Error("a notelemetry query must not create a node file")
446		}
447	
448		// A late duplicate replay reports duplicate=1 and leaves the file bytes
449		// identical (deterministic encoding of unchanged records).
450		dupOut, errOut, c := runCLI(t, dir, "["+reconnectFreshRecord+"]",
451			"heartbeat", "submit", "--data-dir", dir, "--receive-time", "2026-10-01T12:05:00Z")
452		if c != 0 || !strings.Contains(dupOut, "new=0 duplicate=1") {
453			t.Fatalf("duplicate replay: code=%d out=%q err=%q", c, dupOut, errOut)
454		}
455	
456		for node, want := range before {
457			if got := readNodeFile(t, dir, node); got != want {
458				t.Errorf("saved file for %q changed during queries, failures or duplicate replay", node)
459			}
460		}
461	
462		// History semantics after all the reads: the fresh small seq is still the
463		// first record, not promoted or refreshed by anything.
464		lines := historyLines(t, dir, reconnectNode)
465		if len(lines) != 2 || !strings.Contains(lines[0], "seq=5") || !strings.Contains(lines[1], "seq=10") {
466			t.Errorf("history after read-only activity = %q", lines)
467		}
468	}
